/* Bit positions of the bitfields Rust reads, checked once at startup. */
static inline int rustLayoutBitAt(const void *p, size_t size, unsigned bit) {
    const unsigned char *b = p;
    for (size_t i = 0; i < size; i++)
        if (b[i] != (i == bit / 8 ? 1u << (bit % 8) : 0)) return 0;
    return 1;
}

#define RUST_LAYOUT_BIT(T, f, bit)                                    \
    do {                                                              \
        T _v;                                                         \
        memset(&_v, 0, sizeof(_v));                                   \
        _v.f = 1;                                                     \
        if (!rustLayoutBitAt(&_v, sizeof(_v), bit)) return #T "." #f; \
    } while (0)

/* Returns NULL, or the name of the first bitfield that moved. */
